-- TI-682 lot D, PR 2 (migration …_takeoff_page_decisions.sql): the database guard reads « the same page » and the
-- earlier contribution of a page with SQL twins of the TypeScript reader of PR 1 (src/lib/takeoff/page-contributions.ts).
-- Both run the same vectors: src/lib/takeoff/page-contributions-vectors.test.ts runs the TypeScript reader on
-- page-contributions.vectors.json and checks that the copy embedded below is identical; this file runs the SQL twins on
-- that copy. A disagreement on any case is a red test on one side or the other.
-- Isolation justified: these are the pure functions the guard is made of; no journey can seed one case per page identity.
-- Written before the migration: red on main (the functions do not exist). All values are fictional.
begin;

create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_catalog;
set local client_min_messages = warning;
select no_plan();

create temporary table page_vectors on commit drop as select $vectors$
