}
$vectors$::jsonb as value;

-- « The same page », both ways (isSamePage).
select is(private.takeoff_same_page(entry.value -> 'left', entry.value -> 'right'), (entry.value ->> 'expected')::boolean,
  'same page: ' || (entry.value ->> 'name'))
from page_vectors, jsonb_array_elements(page_vectors.value -> 'same_page') as entry(value);
select is(private.takeoff_same_page(entry.value -> 'right', entry.value -> 'left'), (entry.value ->> 'expected')::boolean,
  'same page, the other way: ' || (entry.value ->> 'name'))
from page_vectors, jsonb_array_elements(page_vectors.value -> 'same_page') as entry(value);

-- The page a takeoff line reads (takeoffLinePageIdentity): its file and page, its source document and its job's sources.
select is(private.takeoff_line_page_identity(entry.value #>> '{line,source_file_name}',
    (entry.value #>> '{line,source_page}')::integer, entry.value #> '{line,source_document}', entry.value -> 'sources'),
  nullif(entry.value -> 'expected', 'null'::jsonb),
  'line identity: ' || (entry.value ->> 'name'))
from page_vectors, jsonb_array_elements(page_vectors.value -> 'line_identity') as entry(value);

-- The takeoff lines an estimate line comes from (estimateLineTakeoffItemIds), in the order read.
select is(to_jsonb(private.takeoff_estimate_line_item_ids(nullif(entry.value -> 'source_metadata', 'null'::jsonb),
    (entry.value ->> 'source_job_id')::uuid)), entry.value -> 'expected',
  'source lines: ' || (entry.value ->> 'name'))
from page_vectors, jsonb_array_elements(page_vectors.value -> 'line_item_ids') as entry(value);

-- The pages already in the estimate (findPagesAlreadyInEstimate): rows, lines, earlier takeoffs and their order.
select is(private.takeoff_pages_already_in_estimate((entry.value ->> 'job_id')::uuid, entry.value -> 'new_lines',
    entry.value -> 'estimate_lines', entry.value -> 'earlier_items', coalesce(entry.value -> 'job_sources', '{}'::jsonb)), entry.value -> 'expected',
  'pages already in the estimate: ' || (entry.value ->> 'name'))
from page_vectors, jsonb_array_elements(page_vectors.value -> 'pages') as entry(value);

-- No case is lost on the way: as many assertions as the file holds.
select is((select jsonb_array_length(value -> 'same_page') + jsonb_array_length(value -> 'line_identity')
    + jsonb_array_length(value -> 'line_item_ids') + jsonb_array_length(value -> 'pages') from page_vectors), 64,
  'the SQL twin reads all 64 vectors');

-- The twins are internal: no client role runs them.
select ok(not has_function_privilege('authenticated', 'private.takeoff_pages_already_in_estimate(uuid,jsonb,jsonb,jsonb,jsonb)', 'execute'),
  'authenticated cannot run the page reader directly');

select * from finish();
rollback;
